parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "results": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "excerpt": {
            "type": "string",
            "description": "Relevant excerpt retrieved from the knowledge base."
          },
          "source": {
            "type": "string",
            "description": "Original source filename of the retrieved excerpt."
          }
        },
        "required": [
          "excerpt",
          "source"
        ]
      }
    },
    "no_relevant_information": {
      "type": "boolean",
      "description": "Whether sufficiently relevant information was found in the knowledge base."
    }
  },
  "required": [
    "results",
    "no_relevant_information"
  ]
}
